import * as THREE from "three";
// Type-only. Importing the `Surface` *class* here pulled its whole dependency
// chain — messenger, the container store, and `compute/csg`, whose modeling
// bundle top-level-awaits a browser URL — into the ray tracer's numerical core,
// which is why nothing in `__tests__/` could execute `traceRay` and every spec
// in this directory tests the source text instead. The one runtime use was an
// `instanceof` guarding a hit counter; it is duck-typed below, the way
// `SurfaceProperties.tsx` already checks for the same property.
import type Surface from "../../objects/surface";
import { probability } from '../../common/probability';
import { BandEnergy, Chain, RayPath, SELF_INTERSECTION_OFFSET } from "./types";
import { reflectDirection, worldHitNormal } from "./world-normal";

const { abs } = Math;

// Pre-allocated scratch vectors to avoid per-ray allocations
const _negRd = new THREE.Vector3();
const _normalCopy = new THREE.Vector3();
const _normalScaled = new THREE.Vector3();
const _reflectedDir = new THREE.Vector3();
const _scatterCandidate = new THREE.Vector3();
const _offsetOrigin = new THREE.Vector3();
const _arrivalDir = new THREE.Vector3();

const _plane = new THREE.Plane();
const _pleq = new THREE.Vector4();
const _avec4 = new THREE.Vector4();
const _bvec4 = new THREE.Vector4();
const _cvec4 = new THREE.Vector4();

export function inFrontOf(a: THREE.Triangle, b: THREE.Triangle) {
  a.getPlane(_plane);
  _pleq.set(_plane.normal.x, _plane.normal.y, _plane.normal.z, _plane.constant);
  _avec4.set(b.a.x, b.a.y, b.a.z, 1);
  _bvec4.set(b.b.x, b.b.y, b.b.z, 1);
  _cvec4.set(b.c.x, b.c.y, b.c.z, 1);
  return _pleq.dot(_avec4) > 0 || _pleq.dot(_bvec4) > 0 || _pleq.dot(_cvec4) > 0;
}

/**
 * A receiver crossing as a finished path: the chain so far plus the receiver,
 * with air absorption over the last segment.
 */
function receiverArrival(
  hit: THREE.Intersection,
  rd: THREE.Vector3,
  bandEnergy: BandEnergy,
  cachedAirAtt: number[],
  chain: Partial<Chain>[],
  source: string,
  initialPhi: number,
  initialTheta: number,
): RayPath {
  const nWorld = worldHitNormal(hit, _normalCopy, rd);
  const angle = nWorld && _negRd.copy(rd).multiplyScalar(-1).angleTo(nWorld);

  // apply air absorption for the final segment to the receiver
  const receiverSegmentDist = hit.distance;
  const receiverBandEnergy = bandEnergy.map((e, f) =>
    e * Math.pow(10, -cachedAirAtt[f] * receiverSegmentDist / 10)
  );

  // broadband average energy for scalar backward compat (recompute after air absorption)
  const receiverTotalEnergy = receiverBandEnergy.reduce((a, b) => a + b, 0);
  const receiverEnergy = receiverBandEnergy.length > 0 ? receiverTotalEnergy / receiverBandEnergy.length : 0;

  // The chain so far plus the receiver. A copy of the array: with
  // pass-through (#234) the ray carries on and keeps appending to `chain`.
  // The entries themselves are shared with it, which is safe because a hop
  // is never changed after it is pushed; copy them too if that ever changes.
  const arrivalChain = [
    ...chain,
    {
      object: hit.object.parent!.uuid,
      angle: angle!,
      distance: hit.distance,
      faceNormal: nWorld
        ? [nWorld.x, nWorld.y, nWorld.z]
        : [hit.face!.normal.x, hit.face!.normal.y, hit.face!.normal.z],
      faceMaterialIndex: hit.face!.materialIndex,
      faceIndex: hit.faceIndex!,
      point: [hit.point.x, hit.point.y, hit.point.z],
      energy: receiverEnergy,
      bandEnergy: [...receiverBandEnergy],
    } as Partial<Chain>,
  ];

  // Compute arrival direction (direction ray arrives FROM, normalized)
  // This is the opposite of the ray direction (ray travels toward receiver)
  _arrivalDir.copy(rd).normalize().negate();
  const arrivalDirection: [number, number, number] = [_arrivalDir.x, _arrivalDir.y, _arrivalDir.z];

  return {
    chain: arrivalChain,
    chainLength: arrivalChain.length,
    intersectedReceiver: true,
    energy: receiverEnergy,
    bandEnergy: [...receiverBandEnergy],
    source,
    initialPhi,
    initialTheta,
    arrivalDirection,
  } as RayPath;
}

/**
 * Trace one ray through its reflections.
 *
 * ## Receivers (#234)
 *
 * With an `arrivals` collector, a ray **passes through** receivers. Every
 * receiver the ray crosses before the next wall is recorded there as an
 * arrival (a path ending at the receiver), and the ray then reflects off that
 * wall as if the receiver were not there. The return value is the ray's own
 * path, however it ended. Ending a ray at its first receiver, as before, took
 * it out of every later time bin: a loss of `c·πr²/V` per second on top of
 * the walls, which read T30 3–8% short in `rt60-cross-check.spec.ts`'s room.
 *
 * Without a collector it keeps the old behaviour, returning the first
 * arrival and ending there, so callers that expect one path per ray are
 * unchanged.
 */
export function traceRay(
  raycaster: THREE.Raycaster,
  intersectableObjects: THREE.Object3D[],
  frequencies: number[],
  cachedAirAtt: number[],
  rrThreshold: number,
  ro: THREE.Vector3,
  rd: THREE.Vector3,
  order: number,
  bandEnergy: BandEnergy,
  source: string,
  initialPhi: number,
  initialTheta: number,
  iter: number = 1,
  chain: Partial<Chain>[] = [],
  arrivals?: RayPath[],
): RayPath | undefined {
  // normalize the ray
  rd = rd.normalize();

  // set the starting position
  raycaster.ray.origin = ro;

  // set the direction
  raycaster.ray.direction = rd;

  // find the surface that the ray intersects
  const intersections = raycaster.intersectObjects(intersectableObjects, true);

  // if there was an intersection
  if (intersections.length > 0) {

    // broadband average energy for scalar backward compat
    const totalEnergy = bandEnergy.reduce((a, b) => a + b, 0);
    const energy = bandEnergy.length > 0 ? totalEnergy / bandEnergy.length : 0;

    // Receivers before the first wall, nearest first. A double-sided sphere
    // is hit on the way in and on the way out; only the entry counts.
    let wall = 0;
    const crossed = new Set<string>();
    while (wall < intersections.length && intersections[wall].object.userData?.kind === 'receiver') {
      const hit = intersections[wall];
      const id = hit.object.parent!.uuid;
      if (!crossed.has(id)) {
        crossed.add(id);
        const arrival = receiverArrival(hit, rd, bandEnergy, cachedAirAtt, chain, source, initialPhi, initialTheta);
        // Without a collector, end here as the ray always used to.
        if (!arrivals) return arrival;
        arrivals.push(arrival);
      }
      wall++;
    }
    // Through the receiver(s) and out of the model.
    if (wall >= intersections.length) return undefined;
    if (wall > 0) intersections.splice(0, wall);

    {
      const nWorld = worldHitNormal(intersections[0], _normalCopy, rd);
      const angle = nWorld && _negRd.copy(rd).multiplyScalar(-1).angleTo(nWorld);

      // push the intersection onto the chain. `faceNormal` is the world-space
      // normal *as this ray saw it* — flipped to face the incoming direction
      // where the triangle is wound the other way — which is the same vector
      // the angle, the reflection and the next origin are computed from. It is
      // recorded rather than the geometric normal because nothing downstream
      // reads it for physics, and a chain entry that disagreed with the bounce
      // it describes would be worse than one that cannot distinguish a
      // back-face hit.
      chain.push({
        object: intersections[0].object.parent!.uuid,
        angle: angle!,
        distance: intersections[0].distance,
        faceNormal: nWorld
          ? [nWorld.x, nWorld.y, nWorld.z]
          : [0, 0, 0],
        faceMaterialIndex: intersections[0].face!.materialIndex,
        faceIndex: intersections[0].faceIndex!,
        point: [intersections[0].point.x, intersections[0].point.y, intersections[0].point.z],
        energy,
      });

      // Anything carrying a numeric `numHits` gets it bumped. In a real scene
      // that is exactly the `Surface` instances the `instanceof` used to match,
      // since nothing else in the hierarchy declares it.
      const hitParent = intersections[0].object.parent as { numHits?: number } | null;
      if (hitParent && typeof hitParent.numHits === "number") {
        hitParent.numHits += 1;
      }

      const normal = nWorld;

      let rr = normal && reflectDirection(rd, normal, _reflectedDir);

      // compute energy-weighted broadband scattering for directional decision
      const surface = intersections[0].object.parent as Surface;
      const scatterCoeffs = frequencies.map(f => surface.scatteringFunction(f));
      const totalEnergy = bandEnergy.reduce((a, b) => a + b, 0) || 1;
      let broadbandScattering = 0;
      for (let f = 0; f < frequencies.length; f++) {
        broadbandScattering += scatterCoeffs[f] * (bandEnergy[f] || 0);
      }
      broadbandScattering /= totalEnergy;

      if (probability(broadbandScattering)) {
        // Cosine-weighted (Lambertian) hemisphere sampling via rejection method
        do {
          _scatterCandidate.set(
            Math.random() * 2 - 1,
            Math.random() * 2 - 1,
            Math.random() * 2 - 1
          );
        } while (_scatterCandidate.lengthSq() > 1 || _scatterCandidate.lengthSq() < 1e-6);
        _scatterCandidate.normalize();
        // Offset along normal for cosine-weighted distribution
        rr = _reflectedDir.copy(_scatterCandidate).add(normal!).normalize();
      }

      // apply per-band reflection loss
      const segmentDistance = intersections[0].distance;
      const newBandEnergy = frequencies.map((frequency, f) => {
        const e = bandEnergy[f];
        if (e == null) return 0;
        // surface reflection
        let energy = e * abs(surface.reflectionFunction(frequency, angle!));
        // per-segment air absorption (intensity domain: /10)
        energy *= Math.pow(10, -cachedAirAtt[f] * segmentDistance / 10);
        return energy;
      });

      // Russian Roulette termination: unbiased probabilistic early termination
      const maxEnergy = Math.max(...newBandEnergy);
      if (rr && normal && iter < order + 1) {
        if (maxEnergy < rrThreshold && maxEnergy > 0) {
          const survivalProbability = maxEnergy / rrThreshold;
          if (Math.random() > survivalProbability) {
            // Terminate ray - expected value preserved (no bias)
            const rrTotalEnergy = newBandEnergy.reduce((a, b) => a + b, 0);
            const rrEnergy = newBandEnergy.length > 0 ? rrTotalEnergy / newBandEnergy.length : 0;
            return { chain, chainLength: chain.length, source, intersectedReceiver: false, energy: rrEnergy, bandEnergy: [...newBandEnergy] } as RayPath;
          }
          // Boost surviving ray energy to compensate
          for (let f = 0; f < newBandEnergy.length; f++) {
            newBandEnergy[f] /= survivalProbability;
          }
        }
        if (maxEnergy > 0) {
          // recurse
          return traceRay(
            raycaster,
            intersectableObjects,
            frequencies,
            cachedAirAtt,
            rrThreshold,
            _offsetOrigin.copy(intersections[0].point).addScaledVector(normal, SELF_INTERSECTION_OFFSET),
            rr,
            order,
            newBandEnergy,
            source,
            initialPhi,
            initialTheta,
            iter + 1,
            chain,
            arrivals,
          );
        }
      }
    }
    return { chain, chainLength: chain.length, source, intersectedReceiver: false } as RayPath;
  }
}
